head.b:skin:
:root {
  --bg-dark: #0f1117;
  --bg-panel: #1e212b;
  --bg-message: #282c38;
  --primary: #6c5ce7;
  --primary-hover: #5b4bc4;
  --text-main: #e0e0e0;
  --text-muted: #9ca3af;
  --border: #333842;
  --code-header: #2d313c;
  --font-ui: 'Inter', sans-serif;
  --font-code: 'JetBrains Mono', monospace;
}

* { box-sizing: border-box; margin: 0; padding: 0; outline: none; }
body, html { height: 100%; overflow: hidden; font-family: var(--font-ui); background: var(--bg-dark); color: var(--text-main); }

/* Ocultar elementos do Blogger */
.navbar, .blog-posts, .sidebar, .footer, .widget-content, iframe[name^="google"], .blogger-style-notice { display: none !important; }

/* ---- LAYOUT PRINCIPAL ---- */
#app-container { display: flex; height: 100vh; width: 100%; position: relative; }

/* SIDEBAR */
#sidebar {
  width: 260px; background: var(--bg-panel); border-right: 1px solid var(--border);
  display: flex; flex-direction: column; flex-shrink: 0; transition: transform 0.3s ease;
  z-index: 100;
}
.sidebar-header { padding: 15px; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center; }
.logo { font-weight: 700; color: #fff; display: flex; align-items: center; gap: 8px; }
.new-chat-btn {
  background: var(--primary); color: white; border: none; padding: 10px; width: 100%;
  margin: 15px 0 0 0; border-radius: 8px; cursor: pointer; font-weight: 600; display: flex; align-items: center; justify-content: center; gap: 8px; transition: 0.2s;
}
.new-chat-btn:hover { background: var(--primary-hover); }

#chat-list { flex: 1; overflow-y: auto; padding: 10px; display: flex; flex-direction: column; gap: 5px; }
.chat-item {
  padding: 10px 12px; border-radius: 8px; cursor: pointer; color: var(--text-muted);
  font-size: 0.9rem; display: flex; justify-content: space-between; align-items: center; group;
  transition: 0.2s;
}
.chat-item:hover { background: rgba(255,255,255,0.05); color: #fff; }
.chat-item.active { background: rgba(108, 92, 231, 0.2); color: var(--primary); border: 1px solid rgba(108, 92, 231, 0.3); }
.chat-title { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 180px; }
.delete-chat { opacity: 0; background: none; border: none; color: #ff5555; cursor: pointer; padding: 4px; }
.chat-item:hover .delete-chat { opacity: 1; }

/* SETTINGS BUTTON FOOTER */
.sidebar-footer { padding: 15px; border-top: 1px solid var(--border); }
.settings-btn { background: transparent; color: var(--text-muted); border: none; display: flex; align-items: center; gap: 8px; cursor: pointer; width: 100%; padding: 8px; border-radius: 6px; }
.settings-btn:hover { background: rgba(255,255,255,0.05); color: #fff; }

/* ÁREA PRINCIPAL */
#main-area { flex: 1; display: flex; flex-direction: column; height: 100%; position: relative; min-width: 0; }

header {
  height: 60px; padding: 0 20px; display: flex; align-items: center; justify-content: space-between;
  border-bottom: 1px solid var(--border); background: var(--bg-dark);
}
.mobile-menu-btn { display: none; background: none; border: none; color: #fff; cursor: pointer; margin-right: 15px; }
.model-badge { font-size: 0.75rem; background: #2a2a2a; padding: 4px 10px; border-radius: 12px; color: #aaa; border: 1px solid var(--border); }

/* CHAT BOX */
#chat-box { flex: 1; overflow-y: auto; padding: 20px; display: flex; flex-direction: column; gap: 20px; scroll-behavior: smooth; }

.msg-row { display: flex; width: 100%; margin-bottom: 10px; }
.msg-row.user { justify-content: flex-end; }
.msg-row.ai { justify-content: flex-start; }

.bubble { max-width: 85%; padding: 15px; border-radius: 12px; line-height: 1.6; position: relative; word-wrap: break-word; }
.bubble.user { background: var(--bg-message); color: #fff; border-bottom-right-radius: 2px; }
.bubble.ai { background: transparent; color: #ddd; padding: 0 15px; max-width: 100%; width: 100%; }

/* ESTILOS DE CÓDIGO E MARKDOWN */
.bubble.ai p { margin-bottom: 1em; }
.bubble.ai ul, .bubble.ai ol { margin-left: 20px; margin-bottom: 1em; }

/* BLOCO DE CÓDIGO PERSONALIZADO */
.code-block-wrapper {
  background: #0d0d0d; border-radius: 8px; border: 1px solid var(--border);
  margin: 15px 0; overflow: hidden;
}
.code-header {
  display: flex; justify-content: space-between; align-items: center;
  background: var(--code-header); padding: 6px 12px; border-bottom: 1px solid var(--border);
}
.lang-label { font-family: var(--font-code); font-size: 0.75rem; color: #aaa; text-transform: uppercase; }
.code-actions { display: flex; gap: 8px; }
.action-btn {
  background: transparent; border: none; color: #aaa; cursor: pointer;
  display: flex; align-items: center; gap: 4px; font-size: 0.75rem; padding: 4px 8px; border-radius: 4px; transition: 0.2s;
}
.action-btn:hover { background: rgba(255,255,255,0.1); color: #fff; }
.action-btn svg { width: 14px; height: 14px; }

pre { margin: 0 !important; padding: 15px; overflow-x: auto; }
code { font-family: var(--font-code) !important; font-size: 0.9rem; }

/* INPUT AREA */
.input-area { padding: 20px; background: var(--bg-dark); border-top: 1px solid var(--border); }
.input-container {
  position: relative; background: var(--bg-panel); border: 1px solid var(--border);
  border-radius: 12px; padding: 10px; display: flex; gap: 10px; align-items: flex-end;
  transition: border-color 0.2s;
}
.input-container:focus-within { border-color: var(--primary); }
textarea {
  flex: 1; background: transparent; border: none; color: #fff; resize: none;
  height: 24px; max-height: 200px; font-family: var(--font-ui); font-size: 1rem;
  line-height: 1.5; padding: 0 5px;
}
.send-btn {
  background: var(--primary); border: none; width: 36px; height: 36px; border-radius: 8px;
  display: flex; align-items: center; justify-content: center; cursor: pointer; transition: 0.2s; flex-shrink: 0;
}
.send-btn:hover { background: var(--primary-hover); }
.send-btn:disabled { opacity: 0.5; cursor: not-allowed; background: #444; }

/* RESPONSIVIDADE */
@media (max-width: 768px) {
  #sidebar {
    position: absolute; left: 0; top: 0; height: 100%;
    transform: translateX(-100%); box-shadow: 2px 0 10px rgba(0,0,0,0.5);
  }
  #sidebar.active { transform: translateX(0); }
  .mobile-menu-btn { display: block; }
  .overlay {
    position: fixed; top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0,0,0,0.7); z-index: 90; display: none; backdrop-filter: blur(2px);
  }
  .overlay.active { display: block; }
}

/* MODAL GENÉRICO */
.modal-overlay {
  position: fixed; top: 0; left: 0; width: 100%; height: 100%;
  background: rgba(0,0,0,0.85); z-index: 1000; display: none;
  justify-content: center; align-items: center;
}
.modal-overlay.active { display: flex; }
.modal { background: var(--bg-panel); padding: 25px; width: 90%; max-width: 500px; border-radius: 12px; border: 1px solid var(--border); }
.form-group { margin-bottom: 15px; }
.form-group label { display: block; margin-bottom: 8px; color: #aaa; font-size: 0.9rem; }
.form-control {
  width: 100%; padding: 12px; background: #111; border: 1px solid var(--border);
  color: #fff; border-radius: 6px; outline: none; font-family: var(--font-ui);
}
.form-control:focus { border-color: var(--primary); }

/* MODAL DE PREVIEW DE CÓDIGO */
#preview-modal .modal { width: 95%; max-width: 1000px; height: 80vh; display: flex; flex-direction: column; padding: 0; overflow: hidden; }
.preview-header { padding: 10px 20px; background: #111; border-bottom: 1px solid var(--border); display: flex; justify-content: space-between; align-items: center; }
#preview-frame { width: 100%; height: 100%; border: none; background: #fff; }

body.script:
// 

// CONFIGURAÇÃO DO MARKED (RENDERIZADOR DE MARKDOWN)
const renderer = new marked.Renderer();

// Customização do bloco de código
renderer.code = function(code, language) {
  const validLang = language || 'texto';
  const escapedCode = code.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#039;");

  // Botão de executar aparece apenas para HTML
  const showRun = validLang.toLowerCase() === 'html' || validLang.toLowerCase() === 'xml';

  return `
    <div class="code-block-wrapper">
      <div class="code-header">
        <span class="lang-label">${validLang}</span>
        <div class="code-actions">
          ${showRun ? `<button class="action-btn" onclick="App.runCode(this)" title="Executar Preview">
            <svg viewBox="0 0 24 24" fill="currentColor"><path d="M8 5v14l11-7z"/></svg> Preview
          </button>` : ''}
          <button class="action-btn" onclick="App.downloadCode(this, '${validLang}')" title="Baixar">
            <svg viewBox="0 0 24 24" fill="currentColor"><path d="M19 9h-4V3H9v6H5l7 7 7-7zM5 18v2h14v-2H5z"/></svg>
          </button>
          <button class="action-btn" onclick="App.copyCode(this)" title="Copiar">
            <svg viewBox="0 0 24 24" fill="currentColor"><path d="M16 1H4c-1.1 0-2 .9-2 2v14h2V3h12V1zm3 4H8c-1.1 0-2 .9-2 2v14c0 1.1.9 2 2 2h11c1.1 0 2-.9 2-2V7c0-1.1-.9-2-2-2zm0 16H8V7h11v14z"/></svg>
          </button>
        </div>
      </div>
      <pre><code class="language-${validLang}">${escapedCode}</code></pre>
      <div style="display:none;" class="raw-code">${escapedCode}</div>
    </div>
  `;
};
marked.use({ renderer });

// --- UI MODULE ---
const UI = {
  chatBox: document.getElementById('chat-box'),
  userInput: document.getElementById('user-input'),
  sidebar: document.getElementById('sidebar'),
  overlay: document.getElementById('mobile-overlay'),
  chatList: document.getElementById('chat-list'),

  init() {
    this.userInput.addEventListener('input', function() {
      this.style.height = 'auto';
      this.style.height = (this.scrollHeight) + 'px';
    });
    this.userInput.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); App.sendMessage(); }
    });
    this.updateModelBadge();
  },

  toggleSidebar() {
    this.sidebar.classList.toggle('active');
    this.overlay.classList.toggle('active');
  },

  openSettings() {
    document.getElementById('api-key').value = localStorage.getItem('groq_key') || '';
    document.getElementById('model-input').value = localStorage.getItem('groq_model') || 'llama-3.1-70b-versatile';
    document.getElementById('system-prompt').value = localStorage.getItem('groq_system') || '';
    document.getElementById('settings-modal').classList.add('active');
  },

  closeSettings() {
    document.getElementById('settings-modal').classList.remove('active');
  },

  updateModelBadge() {
    document.getElementById('current-model-badge').innerText = localStorage.getItem('groq_model') || 'Não configurado';
  },

  setLoading(loading) {
    document.getElementById('typing-indicator').style.display = loading ? 'block' : 'none';
    document.getElementById('btn-submit').disabled = loading;
    this.chatBox.scrollTop = this.chatBox.scrollHeight;
  },

  renderMessages(messages) {
    this.chatBox.innerHTML = '';
    messages.forEach(msg => {
      if (msg.role === 'system') return;
      this.appendMessage(msg.role, msg.content);
    });
  },

  appendMessage(role, text) {
    const row = document.createElement('div');
    row.className = `msg-row ${role === 'user' ? 'user' : 'ai'}`;

    const bubble = document.createElement('div');
    bubble.className = `bubble ${role === 'user' ? 'user' : 'ai'}`;

    if (role === 'assistant') {
      bubble.innerHTML = marked.parse(text);
      bubble.querySelectorAll('pre code').forEach(block => hljs.highlightElement(block));
    } else {
      bubble.innerText = text;
    }

    row.appendChild(bubble);
    this.chatBox.appendChild(row);
    this.chatBox.scrollTop = this.chatBox.scrollHeight;
  }
};

// --- APP LOGIC ---
const App = {
  chats: [],
  currentChatId: null,

  init() {
    UI.init();
    this.loadChats();
    const savedKey = localStorage.getItem('groq_key');

    if (!savedKey) {
      UI.openSettings();
    } else if (this.chats.length === 0) {
      this.createNewChat();
    } else {
      // Carrega o último chat ou o primeiro
      this.loadChat(this.chats[0].id);
    }
  },

  saveSettings() {
    localStorage.setItem('groq_key', document.getElementById('api-key').value.trim());
    localStorage.setItem('groq_model', document.getElementById('model-input').value.trim());
    localStorage.setItem('groq_system', document.getElementById('system-prompt').value.trim());
    UI.closeSettings();
    UI.updateModelBadge();
    alert('Configurações salvas!');
  },

  // --- GERENCIAMENTO DE CHATS ---
  loadChats() {
    const saved = localStorage.getItem('groq_chats');
    this.chats = saved ? JSON.parse(saved) : [];
    this.renderChatList();
  },

  saveChatsToStorage() {
    localStorage.setItem('groq_chats', JSON.stringify(this.chats));
    this.renderChatList();
  },

  createNewChat() {
    const newChat = {
      id: Date.now().toString(),
      title: 'Novo Chat',
      messages: [{ role: "system", content: localStorage.getItem('groq_system') || "Você é um assistente útil." }]
    };
    this.chats.unshift(newChat);
    this.saveChatsToStorage();
    this.loadChat(newChat.id);
    if(window.innerWidth <= 768) UI.toggleSidebar();
  },

  loadChat(id) {
    this.currentChatId = id;
    const chat = this.chats.find(c => c.id === id);
    if (!chat) return;

    document.getElementById('header-title').innerText = chat.title;
    UI.renderMessages(chat.messages);
    this.renderChatList(); // Atualiza classe active
  },

  deleteChat(e, id) {
    e.stopPropagation();
    if(!confirm('Apagar este chat?')) return;
    this.chats = this.chats.filter(c => c.id !== id);
    this.saveChatsToStorage();

    if (this.chats.length > 0) {
      this.loadChat(this.chats[0].id);
    } else {
      this.createNewChat();
    }
  },

  renderChatList() {
    UI.chatList.innerHTML = '';
    this.chats.forEach(chat => {
      const el = document.createElement('div');
      el.className = `chat-item ${chat.id === this.currentChatId ? 'active' : ''}`;
      el.onclick = () => { 
        this.loadChat(chat.id);
        if(window.innerWidth <= 768) UI.toggleSidebar();
      };
      el.innerHTML = `
        <span class="chat-title">${chat.title}</span>
        <button class="delete-chat" onclick="App.deleteChat(event, '${chat.id}')">✕</button>
      `;
      UI.chatList.appendChild(el);
    });
  },

  async sendMessage() {
    const text = UI.userInput.value.trim();
    const apiKey = localStorage.getItem('groq_key');
    if (!text || !apiKey) return;

    const chatIndex = this.chats.findIndex(c => c.id === this.currentChatId);
    if (chatIndex === -1) return;

    // Adiciona msg usuario
    UI.appendMessage('user', text);
    this.chats[chatIndex].messages.push({ role: "user", content: text });

    // Atualiza titulo se for a primeira msg
    if (this.chats[chatIndex].messages.length <= 2) {
      this.chats[chatIndex].title = text.substring(0, 30) + (text.length > 30 ? '...' : '');
      document.getElementById('header-title').innerText = this.chats[chatIndex].title;
    }

    this.saveChatsToStorage(); // Salva estado
    UI.userInput.value = '';
    UI.userInput.style.height = 'auto';
    UI.setLoading(true);

    try {
      // Prepara histórico (envia ultimas 10 msgs para economizar tokens)
      const allMsgs = this.chats[chatIndex].messages;
      const context = allMsgs.slice(-10);
      if (context[0] !== allMsgs[0]) {
        context.unshift(allMsgs[0]);
      }

      const res = await fetch('https://api.groq.com/openai/v1/chat/completions', {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          messages: context, 
          model: localStorage.getItem('groq_model'),
          temperature: 0.7 
        })
      });

      const data = await res.json();
      if (data.error) throw new Error(data.error.message);

      const aiText = data.choices[0].message.content;
      UI.appendMessage('assistant', aiText);

      this.chats[chatIndex].messages.push({ role: "assistant", content: aiText });
      this.saveChatsToStorage();

    } catch (err) {
      UI.appendMessage('ai', `⚠️ **Erro:** ${err.message}`);
    } finally {
      UI.setLoading(false);
    }
  },

  // --- FERRAMENTAS DE CÓDIGO ---

  // Recupera o código bruto decodificado
  getRawCode(btn) {
    const wrapper = btn.closest('.code-header').nextElementSibling.nextElementSibling; // .raw-code div
    const txt = document.createElement("textarea");
    txt.innerHTML = wrapper.innerHTML;
    return txt.value;
  },

  copyCode(btn) {
    const code = this.getRawCode(btn);
    navigator.clipboard.writeText(code).then(() => {
      const originalHtml = btn.innerHTML;
      btn.innerHTML = '<span>✓</span>';
      setTimeout(() => btn.innerHTML = originalHtml, 2000);
    });
  },

  downloadCode(btn, lang) {
    const code = this.getRawCode(btn);
    const extMap = { 'javascript': 'js', 'python': 'py', 'html': 'html', 'css': 'css', 'json': 'json' };
    const ext = extMap[lang.toLowerCase()] || 'txt';

    const blob = new Blob([code], { type: 'text/plain' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `codigo.${ext}`;
    a.click();
    window.URL.revokeObjectURL(url);
  },

  runCode(btn) {
    const code = this.getRawCode(btn);
    const modal = document.getElementById('preview-modal');
    const frame = document.getElementById('preview-frame');

    modal.classList.add('active');
    // Injeta o código no iframe
    const blob = new Blob([code], { type: 'text/html' });
    frame.src = URL.createObjectURL(blob);
  }
};

window.onload = () => App.init();
//
